The `sanitize_profile` function currently only checks if `operatingSystems`, `applications`, and `aiSystems` are lists, but does not sanitize or validate the individual items within those lists. This allows clients to persist arbitrary keys and nested structures in the database, which deviates from the documented behavior ('unknown keys are dropped and lists are sanitized to the asset-wizard shape') and poses a data integrity risk. We should recursively sanitize these lists to ensure they only contain the expected fields and types.

```python
def sanitize_profile(data: dict | None) -> dict | None:
    if data is None:
        return None
    if not isinstance(data, dict):
        raise ValueError("profile must be a JSON object")

    env = data.get("environment") if isinstance(data.get("environment"), dict) else {}

    raw_os = data.get("operatingSystems")
    os_list = []
    if isinstance(raw_os, list):
        for item in raw_os:
            if isinstance(item, dict):
                os_list.append({
                    "product": str(item.get("product") or ""),
                    "version": str(item.get("version") or ""),
                    "vendor": str(item.get("vendor") or ""),
                })

    raw_apps = data.get("applications")
    apps_list = []
    if isinstance(raw_apps, list):
        for item in raw_apps:
            if isinstance(item, dict):
                apps_list.append({
                    "product": str(item.get("product") or ""),
                    "version": str(item.get("version") or ""),
                    "vendor": str(item.get("vendor") or ""),
                })

    raw_ai = data.get("aiSystems")
    ai_list = []
    if isinstance(raw_ai, list):
        for item in raw_ai:
            if item is not None:
                ai_list.append(str(item))

    return {
        "version": data.get("version") or 1,
        "operatingSystems": os_list,
        "applications": apps_list,
        "environment": {
            "internetFacing": str(env.get("internetFacing") or "Some"),
            "industry": str(env.get("industry") or "Technology"),
            "criticality": str(env.get("criticality") or "Medium"),
        },
        "aiSystems": ai_list,
    }
```

