There are two reliability issues here:

1. **Aborted Transaction State**: If `load_public_exploits_for_cve` fails, the transaction is aborted. On Postgres, executing any further queries (like `derive_exploit_provenance` in the `except` block) on the same connection will raise an `InFailedSQLTransaction` exception, which propagates out of the function and causes the entire request to 500. We should rollback the transaction and wrap the fallback `derive_exploit_provenance` call in a try-except block.
2. **Pool Exhaustion**: `get_db()` is called outside the `try` block. If connection pool exhaustion occurs, the unhandled exception will propagate and fail the entire request. Wrapping the entire function body in a `try-except` block ensures graceful degradation.

```python
async def _detail_enrich_exploits(cve_key: str, cve: dict) -> dict:
    from db.cache import get_cve_exploits_latest_fetched_at, get_feed_cache_timestamp

    try:
        db = await get_db()
        try:
            public_exploits = await load_public_exploits_for_cve(
                db,
                cve_key,
                has_poc=bool(cve.get("has_poc")),
                source_urls=cve.get("source_urls"),
            )
            provenance = await derive_exploit_provenance(
                db,
                cve_key,
                used_nvd_fallback=bool(public_exploits)
                and not await get_cve_exploits_latest_fetched_at(db, cve_key)
                and not await get_feed_cache_timestamp(db, f"sploitus:{cve_key}"),
            )
            await db.commit()
            return {"public_exploits": public_exploits, "exploit_provenance": provenance}
        except Exception as exc:
            logger.error("Sploitus load failed for %s: %s", cve_key, exc)
            try:
                await db.rollback()
            except Exception:
                pass
            try:
                provenance = await derive_exploit_provenance(db, cve_key)
            except Exception:
                provenance = {"status": "pending", "source": "Sploitus + BRIEFR exploit index", "as_of": None}
            return {"public_exploits": [], "exploit_provenance": provenance}
        finally:
            await db.close()
    except Exception as outer_exc:
        logger.error("Failed to acquire DB or process exploits for %s: %s", cve_key, outer_exc)
        return {
            "public_exploits": [],
            "exploit_provenance": {"status": "pending", "source": "Sploitus + BRIEFR exploit index", "as_of": None}
        }
```

